let routeCleanup=null;
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageKey=classroomStorageKey();
const tracks={hardware:{name:'Hardware & ServiceDesk',short:'Hardware',symbol:'◈',color:'teal',description:'Work the bench. Trace symptoms, inspect components, and bring a computer back to life.'},network:{name:'Networking & operating systems',short:'Networks & OS',symbol:'⌘',color:'blue',description:'Follow the connection. Work with addresses, permissions, networks, and system services.'},ai:{name:'AI literacy & audit',short:'AI & ethics',symbol:'✳',color:'violet',description:'Question the output. Protect privacy, check evidence, and examine the code.'},security:{name:'Ethical cybersecurity',short:'Cybersecurity',symbol:'◇',color:'amber',description:'Investigate responsibly. Triage an incident, reduce access, and patch a simulated weakness.'},coding:{name:'Coding sandbox',short:'Coding sandbox',symbol:'⌨',color:'rose',description:'Write a small program. Run it with fictional inputs, inspect the output, and explain how it works.'}};
let store={version:2,labs:{}};
let foundationRecords=Object.create(null);
function foundationRecordFor(id){return foundationRecords[id]||=(createFoundationRecord(id));}
function hasFoundationWork(){return Object.entries(foundationRecords).some(([id,record])=>getFoundation(id)&&foundationSummary(id,record).hasWork===true);}
let storageAvailable=true;
let deviceStorage;try{deviceStorage=localStorage;}catch{storageAvailable=false;}
let workStorage=createWorkStorage({storage:deviceStorage,key:storageKey,scenarios:SCENARIOS});
let classroomSharingPaused=false;
let reportCleanup=null;
let labView=null;
let labNavigation=null;
let currentLab=null,libraryTrack='all',libraryGrade='all',libraryQuery='',noticeTimer,classroomConnection=null;
function save(){storageAvailable=workStorage.save(store);if(!storageAvailable)showNotice('Device saving is unavailable. Export your private work before leaving.');classroomConnection?.schedule();}
function resetLocalSession(){foundationRecords=Object.create(null);workStorage.pause();classroomConnection?.dispose();classroomConnection=null;classroomSharingPaused=true;labView=null;storageKey=WORK_PREFIX;workStorage=createWorkStorage({storage:deviceStorage,key:storageKey,scenarios:SCENARIOS});store={version:2,labs:{}};renderRoute(false);}
function bindWorkPrivacy(s){mountWorkControls({host:$('#work-privacy'),manager:workStorage,getStore:()=>store,scenarioId:s.id,replaceStore:value=>{store=value;renderRoute(false);},onClear:cleared=>{resetLocalSession();showNotice(cleared?'Local lab data cleared. Downloads and previously submitted records are separate.':'This page’s work is cleared, but device deletion could not be confirmed. Clear this site’s data in browser settings before sharing the profile.');},onChange:()=>{bindWorkPrivacy(s);const status=$('.save-status');if(status)status.textContent=workStatus(store.labs[s.id]||{},workStorage);}});}
window.addEventListener('storage',event=>{if(event.key===CLEAR_WORK_KEY&&event.newValue){resetLocalSession();showNotice('Local lab data was cleared in another tab. This page has stopped saving and sharing.');}});
window.addEventListener('pagehide',()=>{foundationRecords=Object.create(null);labNavigation=null;disposeHardware($('#workspace'));routeCleanup?.();routeCleanup=null;reportCleanup?.();reportCleanup=null;classroomConnection?.dispose();$('#main')?.replaceChildren();if(!workStorage.persistent){labView=null;store={version:2,labs:{}};}});
window.addEventListener('pageshow',event=>{if(event.persisted)renderRoute();});
function hasCodeDraft(){const editor=$('#coding-editor');return !!editor&&currentLab?.track==='coding'&&editor.value!==store.labs[currentLab.id]?.state.code;}
function preserveCodeDraft(){
  if(!hasCodeDraft())return;
  const record=store.labs[currentLab.id];if(!record)return;
  const result=applyWorkspaceAction(currentLab.id,record.state,'save-code',{code:$('#coding-editor').value});
  record.state=result.state;record.verified=false;record.closed=false;
  record.events.push({time:new Date().toISOString(),kind:'info',message:'Draft program preserved when leaving the lab. Run all fixtures to test this version.'});record.events=retainExperimentEvents(currentLab,record.events);save();
}
window.addEventListener('beforeunload',event=>{if(hasFoundationWork()||(!workStorage.persistent&&Object.values(store.labs).some(hasPrivateWork))||$('#student-question')?.value.trim()||hasCodeDraft()){event.preventDefault();event.returnValue='';}});
function showNotice(message){const n=$('#notice');n.textContent=message;n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>{n.hidden=true;},5000);}
function recordFor(scenario){const existing=Object.hasOwn(store.labs,scenario.id)?store.labs[scenario.id]:null;return store.labs[scenario.id]=normalizeLabRecord(scenario,existing);}
function countComplete(){return SCENARIOS.filter(s=>store.labs[s.id]?.closed===true).length;}
function routeLink(route,text,style='button'){return `<a class="${style}" href="#${route}">${text}</a>`;}
function tag(text,extra=''){return `<span class="tag ${extra}">${text}</span>`;}
function trackIcon(track){const paths={hardware:'<rect x="5" y="9" width="27" height="21" rx="3"/><path d="M18 30v7m-7 0h15"/><rect x="36" y="9" width="8" height="28" rx="2"/><path d="M39 15h2m-2 5h2m-2 12h2"/>',network:'<rect x="17" y="4" width="14" height="10" rx="2"/><rect x="3" y="33" width="14" height="10" rx="2"/><rect x="31" y="33" width="14" height="10" rx="2"/><path d="M24 14v9M10 33v-10h28v10M24 23v14"/>',ai:'<path d="m24 4 5 13 13 5-13 5-5 13-5-13-13-5 13-5Z"/><path d="m40 4 1.5 4.5L46 10l-4.5 1.5L40 16l-1.5-4.5L34 10l4.5-1.5Z"/>',security:'<path d="M24 4 40 10v12c0 10-9 17-16 22C17 39 8 32 8 22V10Z"/><path d="m16 24 5 5 11-12"/>',coding:'<path d="m15 12-11 12 11 12m18-24 11 12-11 12M28 6 20 42"/>'};return `<svg class="track-icon" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[track]||paths.hardware}</svg>`;}
function foundationCards(){return `<section class="basics-section wrap" aria-labelledby="basics-heading"><div class="basics-heading"><div><p class="eyebrow">A LITTLE CURIOSITY IS ALL YOU NEED</p><h2 id="basics-heading">Start with the building blocks.</h2></div><p>Meet the parts. Try an idea. Build the confidence to investigate your first ticket.</p></div><div class="basics-grid">${FOUNDATION_LABS.map(lab=>`<a class="basics-card" data-track="${esc(lab.track)}" href="#learn/${esc(lab.id)}"><span class="basics-symbol">${trackIcon(lab.track)}</span><span class="eyebrow">${esc(tracks[lab.track].short)} · BEGINNER</span><h3>${esc(lab.title)}</h3><p>${esc(lab.summary)}</p><span class="text-link">${esc(lab.minutes)} min · Start learning <span aria-hidden="true">→</span></span></a>`).join('')}</div></section>`;}
function sectionHead(eyebrow,title,description=''){return `<div class="section-heading"><p class="eyebrow">${eyebrow}</p><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>`;}
function stationArt(){return `<div class="station-art" aria-hidden="true"><div class="station-floor"></div><div class="station-monitor"><div class="station-screen"><div class="screen-menu"><i></i><i></i><i></i><span>CLASSROOM DESKTOP · HDMI</span></div><div class="screen-signal"><span class="signal-icon">⌁</span><b>No signal</b><small>Check the video cable and input source.</small></div><div class="screen-bottom"><span>Power on</span><span>●</span></div></div><div class="monitor-logo">COLE / LAB 01</div></div><div class="station-stand"></div><div class="station-base"></div><div class="station-tower"><div class="tower-top"></div><div class="tower-front"><i class="power-led"></i><div class="tower-ports">▰<br>▰<br>●</div><div class="tower-vent"></div><span>WORKSTATION 01</span></div><div class="tower-side"><div class="board-traces"></div><div class="hero-fan"><i></i><i></i><i></i><i></i></div><div class="hero-ram"></div><div class="hero-gpu">GRAPHICS</div><div class="hero-ssd">SATA / SSD</div><div class="hero-wire"></div></div></div><div class="station-keyboard"></div><div class="station-cable"></div><span class="part-callout callout-one">01 / FOLLOW THE SIGNAL</span><span class="part-callout callout-two">02 / INSPECT THE HARDWARE</span></div>`;}

function home(){return `<section class="home-hero"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> ALAN “AL” COLE · Mx. COLE</p><h1>Technology should<br><em>make sense.</em></h1><p class="hero-description">I support K–12 technology and build projects that bring together defensive security, responsible AI, and hands-on learning.</p><p class="hero-subtext">Ask a good question. Try something. See what you can figure out at the virtual bench.</p><div class="button-row">${routeLink('labs','Find your first lab <span aria-hidden="true">↗</span>')}${routeLink('projects','Explore my work <span aria-hidden="true">→</span>','button button-outline')}</div><div class="hero-credentials"><span>K–12 IT support</span><span>Cybersecurity at UAlbany</span><span>Future CTE educator</span></div></div><div class="hero-lab-preview"><div class="preview-topline"><span><i class="status-dot"></i> YOUR NEXT “I GET IT” MOMENT</span><span>VIRTUAL EQUIPMENT</span></div>${stationArt()}<div class="hero-learning-path" aria-label="The investigation process"><span><b>01</b> Ask & explore</span><span><b>02</b> Try & test</span><span><b>03</b> Explain why</span></div><a class="preview-ticket" href="#lab/INC-101"><span class="ticket-letter">${trackIcon('hardware')}</span><span><small>YOUR FIRST TICKET · HARDWARE</small><strong>The Blank Monitor</strong></span><span aria-hidden="true">↗</span></a></div></section>
<section class="fact-strip" aria-label="Learning platform at a glance"><div><b>${SCENARIOS.length+FOUNDATION_LABS.length}</b><span>beginner labs & investigations</span></div><div><b>${Object.keys(tracks).length}</b><span>technology pathways</span></div><div><b>7–12</b><span>grade-level starting points</span></div><p>Ask questions. Gather evidence.<br><strong>Understand why the solution works.</strong></p></section>

<section class="section wrap">${sectionHead('WORK WITH PURPOSE','Security, learning, and the people in between.','My projects explore how technology can protect people, explain its decisions, and make room for curiosity.')}<div class="project-feature"><div class="guardian-visual" aria-hidden="true"><div class="browser-chrome"><i></i><i></i><i></i><span>AI Guardian / Web Shield</span></div><div class="guardian-card"><span class="guard-shield">✓</span><small>PAUSE. UNDERSTAND. DECIDE.</small><h3>A clearer view<br>of online risk.</h3><div class="risk-line"><span>Link signals</span><b>Review</b></div><div class="risk-line"><span>Analysis location</span><b>On device</b></div><p>Illustration of the project’s design focus.</p></div></div><div class="project-copy"><p class="eyebrow">FEATURED PROJECT / BROWSER SECURITY</p><h3>AI Guardian Web Shield</h3><p>A privacy-conscious browser-security project that turns locally available page and link signals into plain-language risk guidance.</p><p>It connects the technical work of recognizing suspicious patterns with the human work of making informed decisions.</p><div class="button-row">${routeLink('projects','Explore my projects →','text-link')}<a class="text-link" href="https://chromewebstore.google.com/detail/ai-guardian-web-shield/ipledehmklfhhdpobeogfdhmhdhmnden" target="_blank" rel="noopener noreferrer">Chrome Web Store ↗</a></div></div></div></section>
${foundationCards()}<section class="pathway-section"><div class="wrap section">${sectionHead('FIVE WAYS TO GET CURIOUS','Find your kind of challenge.','Follow a signal, untangle a network, question an AI answer, investigate safely, or write your first program. Every pathway gives you something to figure out.')}<div class="pathway-grid">${Object.entries(tracks).map(([id,t])=>`<a class="pathway-card ${t.color}" data-track="${id}" href="#labs/${id}"><span class="pathway-symbol">${trackIcon(id)}</span><span class="eyebrow">${String(SCENARIOS.filter(s=>s.track===id).length).padStart(2,'0')} INVESTIGATIONS</span><h3>${t.name}</h3><p>${t.description}</p><span class="text-link">Open pathway <span aria-hidden="true">↗</span></span></a>`).join('')}</div></div></section>
<section class="wrap section teaching-intro"><div><p class="eyebrow">FOR THE CLASSROOM</p><h2>The thinking matters<br>as much as the fix.</h2></div><div><p>These labs are built around a repeatable process: understand the request, gather evidence, make a plan, test carefully, and verify the original task.</p><p>Use them for a whole-class demonstration, guided investigation, independent practice, or a discussion about responsible technology.</p>${routeLink('educators','Plan a lesson →','button button-outline')}</div></section>`;}

function projectPage(){return `<section class="page-intro wrap"><p class="eyebrow">PROJECT PORTFOLIO</p><h1>Ideas put<br><em>to work.</em></h1><p>Projects connecting practical IT support with defensive security, responsible AI, and technology education.</p></section><section class="wrap project-list">${[
{n:'01',name:'AI Guardian Web Shield',type:'BROWSER SECURITY · PUBLISHED EXTENSION',text:'People need understandable guidance when a page or link looks suspicious. Web Shield explores local analysis, plain-language explanations, privacy, and informed choices.',bullets:['Local page and link signals','Human-centered risk communication','Privacy-conscious product design'],url:'https://github.com/AL91Cole/ai-guardian-web-shield',link:'Source & documentation'},
{n:'02',name:'AI Guardian Assistant — Project Labyrinth',type:'DEFENSIVE ZERO TRUST · SIMULATION',text:'How should a system handle an access request with conflicting trust signals? Project Labyrinth models identity-aware decisions, audit trails, and decoy containment.',bullets:['Identity, roles, and least privilege','Access decisions and structured logs','Defensive containment through decoys'],url:'https://github.com/AL91Cole/ai-guardian-assistant-project-labyrinth',link:'Explore Project Labyrinth'},
{n:'03',name:'AI Ethics and Moral Philosophy',type:'ONGOING RESEARCH · RESPONSIBLE AI',text:'An evolving research collection examining how dignity, consent, privacy, accountability, and human responsibility can guide technology decisions. Original frameworks are proposals open to discussion and revision.',bullets:['Ethical reasoning and practical governance','Accessibility and meaningful user choice','Accountability, appeal, and repair'],url:'https://github.com/AL91Cole/ai-ethics-and-moral-philosophy',link:'Read the research'},
{n:'04',name:'Cole Learning Labs',type:'INTERACTIVE EDUCATION · GRADES 7–12',text:'A virtual place to investigate technology problems when classroom hardware cannot be taken apart. Learners work with simulated equipment, settings, artifacts, and security events, then explain how they verified the result.',bullets:['29 investigations across five pathways','Evidence, planning, and verification','Browser-local reports and progress'],url:'#labs',link:'Enter the virtual labs'}
].map(p=>`<article class="project-row"><span class="project-number">${p.n}</span><div><p class="eyebrow">${p.type}</p><h2>${p.name}</h2><p>${p.text}</p><ul class="inline-list">${p.bullets.map(b=>`<li>${b}</li>`).join('')}</ul><a class="text-link" href="${p.url}" ${p.url.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${p.link} ↗</a></div></article>`).join('')}</section>`;}
function about(){return `<section class="wrap page-intro about-intro"><div><p class="eyebrow">ABOUT ALAN “AL” COLE</p><h1>People first.<br><em>Always learning.</em></h1><p>I work as a Computer Technical Assistant at Fonda-Fultonville Central School District while studying cybersecurity at the University at Albany.</p></div><aside class="quote-card"><span aria-hidden="true">“</span><blockquote>I build security systems that think before they trust—and explain before they alarm.</blockquote><p>Alan “Al” Cole</p></aside></section><section class="wrap section split-content"><div><p class="eyebrow">THE WORK BEHIND THE LABS</p><h2>Practical support.<br>Thoughtful security.</h2></div><div><p>Working in K–12 IT keeps my interests grounded in everyday needs: a computer that will not start, a connection that fails, a person who needs a clear explanation.</p><p>My projects connect those experiences with identity and access, defensive engineering, responsible AI, and accessible technology education.</p><p>Cole Learning Labs grew from a classroom question: how can students investigate computer hardware when school devices cannot be taken apart? The virtual bench gives them a place to test ideas and learn from the result.</p></div></section><section class="muted-section"><div class="wrap section split-content"><div><p class="eyebrow">EDUCATION & DIRECTION</p><h2>Building toward<br>what comes next.</h2></div><div class="timeline"><article><span>IN PROGRESS · EXPECTED MAY 2027</span><h3>B.S. in Cybersecurity</h3><p>University at Albany (SUNY)<br>Self-designed concentration: AI-Driven Cybersecurity & Ethical Hacking<br>Minor: AI Ethics & Philosophy</p></article><article><span>PROFESSIONAL LEARNING</span><h3>Credentials & hands-on practice</h3><ul><li>Google Cybersecurity Professional Certificate</li><li>CompTIA Security+</li><li>TryHackMe Cyber Security 101 learning path completed</li><li>Professional Certificate in Computer Systems and Networks — American Public University</li></ul></article><article><span>FUTURE GOAL</span><h3>Computer Technology through CTE</h3><p>I am pursuing the path toward Career and Technical Education certification and developing these learning resources along the way.</p></article></div></div></section><section class="wrap section"><p class="eyebrow">AREAS OF FOCUS</p><div class="focus-grid"><article><h3>Systems & support</h3><p>Windows and Linux, endpoint troubleshooting, networking fundamentals, user support, and clear documentation.</p></article><article><h3>Defensive security</h3><p>Zero Trust, identity and access decisions, least privilege, event analysis, and privacy-conscious design.</p></article><article><h3>Development & ethics</h3><p>JavaScript, React, Next.js, Tailwind CSS, SQLite, and continuing Python and PowerShell fundamentals. Human responsibility stays central.</p></article></div><p class="quiet-note">I also founded CTRL+J Juice Lounge & IT Hub™ LLC, a community technology venture whose active development is currently on hold while I focus on education and career goals.</p></section>`;}

function library(){const completed=countComplete();return `<section class="lab-library-intro"><div class="wrap"><p class="eyebrow">CURIOSITY, MEET YOUR WORKBENCH</p><h1>A little exploring.<br><em>A lot of figuring it out.</em></h1><p>Start small with a beginner lab, or investigate a fictional request. You can revisit a clue, change your idea, and try again.</p><div class="library-meta">${tag('Grades 7–12')}${tag(`${FOUNDATION_LABS.length} beginner labs`)}${tag('Virtual equipment · real reasoning')}${tag(`${completed} of ${SCENARIOS.length} delivered`)}</div><div class="library-pathway-markers" aria-hidden="true">${Object.keys(tracks).map(id=>`<span data-track="${id}">${trackIcon(id)}</span>`).join('')}</div></div></section>${foundationCards()}<section class="wrap library-section"><div class="investigation-heading"><div><p class="eyebrow">PICK A PATHWAY. TAKE A TICKET.</p><h2 class="ticket-list-heading">Your next investigation</h2></div><p>Gather clues, test your idea, and tell the story of what worked.</p></div><div class="library-toolbar"><div class="track-filters" role="group" aria-label="Filter by pathway"><button data-track="all" class="${libraryTrack==='all'?'active':''}" aria-pressed="${libraryTrack==='all'}">All pathways</button>${Object.entries(tracks).map(([id,t])=>`<button data-track="${id}" class="${libraryTrack===id?'active':''}" aria-pressed="${libraryTrack===id}">${t.short}</button>`).join('')}</div><div class="library-options"><label>Grade band<select id="grade-filter"><option value="all">All grades</option>${['7–8','9–10','11–12'].map(g=>`<option value="${g}" ${libraryGrade===g?'selected':''}>Grades ${g}</option>`).join('')}</select></label><label>Find a lab<input id="lab-search" type="search" value="${esc(libraryQuery)}" placeholder="Search title or ticket…"></label></div></div><p id="lab-count" class="result-count" aria-live="polite"></p><div class="lab-card-grid" id="lab-results"></div><div class="library-guidance"><span class="pathway-symbol" aria-hidden="true">↗</span><div><h2>Connect all five pathways</h2><p>Prepare a fictional classroom for opening day, then write a technician handoff.</p></div><a class="button button-outline" href="#capstone">Open the capstone →</a></div><div class="library-guidance"><span class="pathway-symbol" aria-hidden="true">?</span><div><h2>First time at the bench?</h2><p>The Student Guide explains the workflow. Private sessions keep work on this page. Device saving is an explicit choice; export a report when you finish.</p></div>${routeLink('guide','Read the student guide →','button button-outline')}</div></section>`;}
function labCards(){const result=SCENARIOS.filter(s=>(libraryTrack==='all'||s.track===libraryTrack)&&(libraryGrade==='all'||s.grade===libraryGrade)&&`${s.id} ${s.title} ${s.summary}`.toLowerCase().includes(libraryQuery.toLowerCase()));$('#lab-count').textContent=`${result.length} investigation${result.length===1?'':'s'} · ${countComplete()} delivered on this browser`;
$('#lab-results').innerHTML=result.length?result.map(s=>`<a class="lab-card ${tracks[s.track].color}" data-track="${s.track}" href="#lab/${s.id}"><div class="lab-card-visual track-${s.track}"><span class="lab-card-code">${s.id}</span><span class="lab-visual-icon">${trackIcon(s.track)}</span><span class="lab-card-status">${store.labs[s.id]?.closed?'✓ Delivered':store.labs[s.id]?'In progress':'Ready to investigate'}</span></div><div class="lab-card-copy"><p class="eyebrow">${tracks[s.track].short} · GRADES ${s.grade}</p><h2>${s.title}</h2>${s.intake?`<p class="request-kind">${s.intake.kind==='follow-up'?'Incomplete request · ask questions':'Detailed request'}</p>`:''}<p>${s.summary}</p><div class="lab-card-foot"><span>${s.minutes} min suggested</span><span>Open bench <span aria-hidden="true">↗</span></span></div></div></a>`).join(''):`<div class="empty-state"><h2>No labs match those filters.</h2><p>Choose another pathway or grade band, or clear your search.</p><button class="button button-outline" id="clear-filters">Clear filters</button></div>`;$('#clear-filters')?.addEventListener('click',()=>{libraryTrack='all';libraryGrade='all';libraryQuery='';history.replaceState(null,'','#labs');renderRoute();});}

function labPage(s){
  const r=recordFor(s),language=labLanguage(s),persona=requesterPersona(s);currentLab=s;if(labView?.id!==s.id)labView={id:s.id,section:1};
  return [
    '<section class="lab-shell single-page-lab paged-lab" data-track="'+esc(s.track)+'"><div class="lab-topbar"><a href="#labs" class="back-link">← All labs</a><div><span class="eyebrow">'+esc(s.id)+' / '+esc(tracks[s.track].name)+'</span><h1>'+esc(s.title)+'</h1></div><span class="tag">GRADES '+esc(s.grade)+'</span><div class="lab-tools"><button id="reading-toggle" class="lab-tool" aria-pressed="false">Larger text</button><button id="saving-options" class="lab-tool">Saving & privacy</button><button id="report-button" class="lab-tool">My report ↗</button></div></div>',
    '<div class="lab-objective"><strong>'+esc(language.goalLabel)+'</strong><p>'+esc(s.goal)+'</p></div>',
    '<div class="lab-page-heading"><p id="lab-page-progress" class="eyebrow">PAGE 1 OF 3</p><h2 id="lab-page-title">Request &amp; clues</h2></div>',

    "<nav class=\"lab-section-nav lab-section-jumps\" aria-label=\"Investigation pages\"><button type=\"button\" id=\"lab-tab-1\" data-lab-section=\"1\" aria-controls=\"lab-problem\" aria-current=\"step\"><span class=\"step-number\">1</span>Request & clues<span class=\"section-done\" aria-hidden=\"true\"></span></button><button type=\"button\" id=\"lab-tab-2\" data-lab-section=\"2\" aria-controls=\"lab-workbench\"><span class=\"step-number\">2</span>Workbench & test<span class=\"section-done\" aria-hidden=\"true\"></span></button><button type=\"button\" id=\"lab-tab-3\" data-lab-section=\"3\" aria-controls=\"lab-finish\" aria-expanded=\"false\"><span class=\"step-number\">3</span>Check & Explain<span class=\"section-done\" aria-hidden=\"true\"></span></button></nav>",

    '<div id="classroom-status"></div><div class="lab-grid">',
    '<aside id="lab-problem" class="case-sidebar" tabindex="0" role="region" aria-labelledby="lab-tab-1"><h2 class="lab-section-heading">1. Request &amp; clues</h2><section class="case-panel"><p class="eyebrow">TICKET REQUEST</p><p class="eyebrow">'+(s.intake?.kind==='follow-up'?'INCOMPLETE REQUEST · ASK FOLLOW-UP QUESTIONS':s.intake?.kind==='detailed'?'DETAILED REQUEST · READY TO INVESTIGATE':'YOUR PRACTICE TASK')+'</p><h2>'+esc(s.requester)+'</h2><blockquote>'+esc(s.brief)+'</blockquote><div class="lab-step-actions"><button class="button" data-jump-section="2">Next: Workbench & test →</button></div><p class="intake-progress" id="intake-progress" role="status">'+esc(inquiryProgress(s,r.events).message)+'</p></section><div id="lab-learning"></div>',
    '<section class="case-panel interview-panel"><div class="requester-profile"><span class="requester-avatar" aria-hidden="true">'+esc(persona.name.slice(0,1))+'</span><div><p class="eyebrow">FICTIONAL REQUESTER</p><h3>'+esc(persona.name)+'</h3><p>'+esc(persona.role)+'</p></div></div><p class="requester-intro">'+esc(persona.intro)+'</p><h2>'+esc(language.requesterHeading)+'</h2><p class="panel-help">'+esc(language.requesterPrompt)+'</p><p class="panel-help">'+esc(s.intake?.kind==='follow-up'?s.intake.missing:language.unknownQuestionPrompt)+'</p><form id="question-form"><label class="lab-field" for="student-question">'+esc(language.questionLabel)+'<textarea id="student-question" maxlength="240" rows="2" placeholder="'+esc(language.questionPlaceholder)+'" aria-describedby="question-help"></textarea></label><button class="button" type="submit">'+esc(language.questionButton)+'</button></form><p id="question-help" class="panel-help">'+esc(language.questionHelp)+'</p><p id="question-response" class="question-response" role="status"></p><p id="reply-source" class="panel-help"></p><div id="question-suggestions" class="interview-suggestions" role="group" aria-label="Suggested follow-up questions" hidden></div><details class="intake-questions"><summary>Optional starter questions</summary>'+s.questions.map((q,i)=>'<button data-question="'+i+'" class="question-button" aria-pressed="'+String(r.questions.includes(i))+'">'+esc(q.label)+' <span>'+(r.questions.includes(i)?'Read':'+')+'</span></button>').join('')+'</details><details class="requester-options" id="requester-options"><summary>Free AI option</summary><p>The fast character works right away. Optional AI makes extra character replies for familiar topics. Only an authored topic code and fictional case go to Cloudflare; your typed question stays here. AI needs internet, has a daily allowance, and may be wrong. No app or model download is needed.</p><label class="requester-choice"><input type="checkbox" data-ai-consent><span>I understand that fictional character topics go to Cloudflare. My typed question stays on this page.</span></label><div class="requester-mode-actions"><button class="lab-tool" type="button" data-ai-check>Check free AI availability</button><label class="requester-choice"><input type="checkbox" data-ai-toggle disabled><span>Use free AI for extra conversation</span></label></div><p data-ai-status role="status">Fast character is on. Free AI awaits privacy review and service setup.</p></details><details class="conversation-history"><summary>Conversation history</summary><p class="panel-help">Extra chat stays in this page session. Only accepted case questions go into your report.</p><div id="interview-history" class="interview-history" role="log" aria-label="Questions and requester replies" aria-live="off">'+interviewList(r)+'</div></details></section>',
    '<details class="case-panel repair-notes"><summary>Clues &amp; evidence</summary><h2>Read two clues</h2><p class="panel-help">'+esc(language.evidencePrompt)+'</p><p class="panel-help">Tap a clue to add it to your report. “Ask first” means the requester needs to supply that detail.</p><div class="clue-buttons">'+s.clues.map(c=>'<button data-clue="'+esc(c.id)+'" class="question-button '+(r.evidence.includes(c.id)?'logged':'')+'" aria-pressed="'+String(r.evidence.includes(c.id))+'">'+esc(c.label)+' <span>'+(r.evidence.includes(c.id)?'Added':'+')+'</span></button>').join('')+'</div><div id="evidence-detail" class="question-response" aria-live="polite"></div></details>',
    '<details class="case-panel guide-plan"><summary>'+esc(language.hypothesisHeading)+'</summary><h2>'+esc(language.hypothesisHeading)+'</h2><label class="lab-field">'+esc(language.hypothesisLabel)+'<textarea id="plan" maxlength="2000" rows="3" placeholder="'+esc(language.hypothesisPlaceholder)+'">'+esc(r.plan)+'</textarea></label><p class="panel-help">'+esc(language.hypothesisHelp)+'</p><div class="lab-step-actions"><button class="button" data-jump-section="2">Next: Workbench & test →</button></div></details></aside>',
    '<div id="lab-workbench" class="bench-column" tabindex="0" role="region" aria-labelledby="lab-tab-2" hidden><h2 class="lab-section-heading">2. Workbench & test</h2><div class="bench-label"><span><i class="status-dot"></i> YOUR PRACTICE WORKSPACE</span><span>VIRTUAL ONLY</span></div><div id="workspace" class="workspace"></div><div id="action-feedback" class="action-feedback" role="status">'+esc(r.events.length?eventMessage(r.events.at(-1)):language.workspaceStart)+'</div><details class="case-panel hypothesis-test"><summary>'+esc(language.testSummary)+'</summary><p class="eyebrow">TEST YOUR IDEA</p><h2>'+esc(language.testHeading)+'</h2><p class="panel-help">'+esc(language.testHypothesisLabel)+'</p><p id="experiment-hypothesis">'+esc(r.plan||language.hypothesisEmpty)+'</p><p class="panel-help">'+esc(s.track==='hardware'?'Use the virtual power and startup controls above, then check the current setup here.':'Save or apply your choices above. This button repeats the workspace test and records the result beside your idea. You do not need to pass two different tests.')+'</p><button class="button" id="run-hypothesis-test">'+esc(language.testButton)+'</button><div id="experiment-result" class="experiment-result" role="status">'+esc(language.testEmpty)+'</div></details><div id="experiment-tools"></div><details class="case-panel bench-log"><summary class="panel-title"><strong>'+esc(language.actionLogLabel)+'</strong><span id="action-count">'+r.events.length+' actions</span></summary><ol id="bench-log">'+eventList(r,s)+'</ol></details><div class="lab-step-actions"><button class="lab-tool" data-jump-section="1">← Back: Request & clues</button><button class="button" data-jump-section="3">Next: Check & Explain →</button></div></div>',
    '<aside id="lab-finish" class="evidence-sidebar" tabindex="0" role="region" aria-labelledby="lab-tab-3" hidden><h2 class="lab-section-heading">3. Check & explain</h2><section class="case-panel"><div class="panel-title"><h2>Explain what you tried</h2><span id="clue-count">'+r.evidence.length+' clues</span></div><section class="collected-clues"><h3>'+esc(language.collectedCluesHeading)+'</h3><div class="evidence-list" id="evidence-list">'+evidenceList(s,r)+'</div></section><label class="lab-field">'+esc(language.notesLabel)+'<textarea id="notes" maxlength="4000" rows="4" placeholder="'+esc(language.notesPlaceholder)+'">'+esc(r.notes)+'</textarea></label><label class="lab-field">'+esc(language.reflectionLabel)+'<textarea id="reflection" maxlength="2000" rows="3" placeholder="'+esc(language.reflectionPlaceholder)+'">'+esc(r.reflection)+'</textarea></label><p class="panel-help">'+esc(language.answerHelp)+'</p></section>',
    '<section class="case-panel verification-panel"><p class="eyebrow">CHECK THE GOAL</p><h2>'+esc(language.verificationHeading)+'</h2><p>'+esc(s.goal)+'</p><button class="button" id="verify-task">'+esc(language.verifyButton)+'</button><div class="verify-result" id="verify-result" role="status">'+(r.verified?'✓ '+esc(language.verifiedStatus):'')+'</div><h3>Before you finish</h3><ul class="lab-finish-checklist">'+(s.intake?.kind==='follow-up'?'<li data-finish-check="inquiry">Clarify the missing request detail <span></span></li>':'')+'<li data-finish-check="clues">Collect two clues <span></span></li><li data-finish-check="plan">'+esc(language.hypothesisHeading)+' <span></span></li><li data-finish-check="notes">Describe what you tried <span></span></li><li data-finish-check="reflection">Explain what you learned <span></span></li><li data-finish-check="verified">'+esc(language.verifyButton)+' <span></span></li></ul><button class="button" id="close-ticket">Finish investigation & open report</button><button class="button button-outline" id="finish-report">Preview my report</button><p class="save-status">'+esc(workStatus(r,workStorage))+'</p><div class="lab-step-actions"><button class="lab-tool" data-jump-section="2">← Back: Workbench & test</button></div><button class="text-button" id="reset-ticket">Start this lab again</button><div id="reset-confirm" hidden><p>This clears this lab’s current work and any saved copy when device saving is on. Export first.</p><button id="confirm-reset" class="lab-tool">Start over</button> <button id="cancel-reset" class="lab-tool">Keep my work</button></div></section></aside></div>',
    '<details class="lab-options"><summary>Help &amp; practice options</summary>'+'<div class="learning-controls"><label for="learning-mode">Practice mode<select id="learning-mode"><option value="guided">Guided · learn the process</option><option value="independent">Independent · choose your tests</option><option value="challenge">Challenge · transfer your skills</option></select></label><p id="learning-mode-description"></p></div><div id="learning-transfer" class="learning-transfer" hidden></div>'+"<div class=\"lab-quick-start\" role=\"note\"><h2>How to use this lab</h2><ol><li><strong>Request & clues.</strong> Read. Ask what is missing. Collect two clues and write your idea.</li><li><strong>Workbench & test.</strong> Change one thing, then test. Save edited settings when shown.</li><li><strong>Check & explain.</strong> Check the goal. Explain your result and open your report.</li></ol><p class=\"lab-page-help\">Each numbered step opens its own page. Use Back, Next, or the numbered buttons to move between them. Your unfinished questions, settings, code, and equipment stay in place while you move through this lab.</p><p class=\"lab-session-note\">Private practice: export before leaving. Device saving is optional. Keep names, emails, student IDs, and passwords out of your work.</p></div>"+'<details class="interview-mode-note"><summary>About these practice replies</summary><p>Each requester has a fictional personality and its own case. Fast replies use a local conversation library, case facts, and supported observations. Everyday chat is for practice and does not unlock clues. Unknown facts stay unknown.</p><p>Optional Cloudflare AI has no installation or model download. Its extra replies can be incorrect and cannot repair equipment, award progress, or add case evidence. Other questions keep using the fast character. AI availability depends on the verified free service setup.</p></details><p class="lab-keyboard-help">Keyboard: Tab moves between controls; Enter or Space selects. Use the numbered buttons to change pages. Left/Right Arrow, Home, and End also select pages when these buttons have focus. Everything is virtual. Keep personal information out of your work.</p></details><div id="work-privacy"></div></section>',
    '<dialog id="lab-dialog"><div id="dialog-content"></div><button id="dialog-close" class="button button-outline">Close</button></dialog>'
  ].join('');
}
function evidenceList(s,r){return r.evidence.length?`<ul>${r.evidence.map(id=>`<li>${esc(s.clues.find(c=>c.id===id)?.text||'Clue recorded')}</li>`).join('')}</ul>`:'<p class="panel-help">'+esc(labLanguage(s).evidenceEmpty)+'</p>';}
function interviewList(r){const pairs=readQuestionEvents(r.events).slice(-8);return pairs.length?pairs.map(pair=>'<article class="interview-pair"><p><strong>You asked:</strong> '+esc(pair.question)+'</p><p><strong>Requester:</strong> '+esc(pair.answer)+'</p></article>').join(''):'<p class="panel-help">Your accepted case questions and replies will appear here.</p>';}
function eventMessage(event){const pair=readQuestionEvents([event])[0];return pair?'Question: '+pair.question+' / Reply: '+pair.answer:(experimentEventText(event)||event.message);}
function eventList(r,s=null){return r.events.length?r.events.slice(-10).map(e=>`<li><time>${new Date(e.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time><span>${esc(eventMessage(e))}</span></li>`).join(''):'<li class="empty-log">'+esc(labLanguage(s).logEmpty)+'</li>';}
function bindLab(s,route=null,{onModeChange=null}={}){
  bindWorkPrivacy(s);
  const r=recordFor(s),language=labLanguage(s),workspace=$('#workspace'),shell=$('.lab-shell');
  const panels=[$('.case-sidebar'),$('.bench-column'),$('.evidence-sidebar')];
  const tabs=$$('[data-lab-section]');
  const context={mode:route?.mode||'guided',sequence:route?.sequence||null};
  const chatPairs=readQuestionEvents(r.events).slice(-8).map(pair=>({...pair,source:'Case reply'}));
  const requester=mountRequesterChat($('#requester-options'),{scenario:s});
  const renderChat=()=>{$('#interview-history').innerHTML=chatPairs.length?chatPairs.map(pair=>'<article class="interview-pair"><p><strong>You asked:</strong> '+esc(pair.question)+'</p><p><strong>'+esc(pair.source)+':</strong> '+esc(pair.answer)+'</p></article>').join(''):interviewList(r);};
  const pageNames=['Request & clues','Workbench & test','Check & Explain'];
  const currentMode=()=>$('#learning-mode')?.value||context.mode;
  const renderBench=()=>{
    if(s.track==='hardware'){
      renderHardware(workspace,s.id,r.state,action);
      setHardwareVisible(workspace,shell.dataset.section==='2');
    }else renderWorkspace(workspace,s,r.state,action);
  };
  function currentTaskResult(){
    if(s.track==='coding'&&$('#coding-editor').value!==r.state.code)return {ok:false,message:'Your editor contains untested changes. Return to the workbench and run all fixtures for this version before checking or finishing.'};
    return s.track==='hardware'?verifyHardware(s.id,r.state):verifyWorkspace(s.id,r.state);
  }
  function jumpToSection(section,moveFocus=true,focusTab=false,writeHistory=true){
    const requested=Number(section);
    const index=Number.isInteger(requested)&&requested>=1&&requested<=3?requested-1:0;
    if(s.track==='hardware'&&index!==1)cancelHardwareInteraction(workspace);
    labView={id:s.id,section:index+1};
    shell.dataset.section=String(index+1);
    tabs.forEach((button,i)=>{if(i===index)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');if(i===2)button.setAttribute('aria-expanded',String(index===2));});
    // Keep controls mounted so unapplied settings, questions, and code survive
    // navigation. Native hidden removes inactive pages from focus and layout.
    panels.forEach((panel,i)=>{panel.hidden=i!==index;});
    $('#lab-page-title').textContent=pageNames[index];
    $('#lab-page-progress').textContent='PAGE '+(index+1)+' OF 3';
    document.title=pageNames[index]+' · '+s.id+' · '+s.title+' · Cole Learning Labs';
    if(s.track==='hardware')setHardwareVisible(workspace,index===1);
    if(writeHistory){
      const hash=labPageHash(s.id,index+1,{mode:currentMode(),sequence:context.sequence});
      if(location.hash!==hash)history.pushState(null,'',hash);
    }
    document.dispatchEvent?.(new CustomEvent('cole:lab-section-change',{detail:{id:s.id,section:index+1}}));
    if(moveFocus){panels[index].scrollTop=0;(focusTab?tabs[index]:panels[index]).focus({preventScroll:true});$('#lab-page-title').scrollIntoView({block:'start',behavior:'instant'});}
  }
  function syncRoute(next,moveFocus=true){
    if(next.page!=='lab'||next.id!==s.id||(next.sequence||null)!==context.sequence)return false;
    if(next.mode!==currentMode()){
      // Browser history can restore an earlier support mode. Only its guidance
      // changes; the mounted workspace and every unfinished draft stay intact.
      onModeChange?.(next.mode);
      context.mode=next.mode;
      $('#learning-mode').value=next.mode;
    }
    jumpToSection(next.section,moveFocus,false,false);
    return true;
  }
  function refreshStatus(){
    const inquiry=inquiryProgress(s,r.events);
    $('#intake-progress').textContent=inquiry.message;
    $$('[data-clue]').forEach(button=>{const clue=s.clues.find(c=>c.id===button.dataset.clue);const available=!clue.requiresFact||inquiry.found.includes(clue.requiresFact);button.setAttribute('aria-disabled',String(!available));button.querySelector('span').textContent=available?(r.evidence.includes(clue.id)?'Added':'+'):'Ask first';});
    const checks={inquiry:inquiry.complete,clues:r.evidence.length>=2,plan:r.plan.trim().length>=12,notes:r.notes.trim().length>=15,reflection:r.reflection.trim().length>=15,verified:r.verified===true};
    const done=[checks.inquiry&&checks.clues&&checks.plan,r.verified,r.closed];
    tabs.forEach((button,index)=>{button.classList.toggle('is-complete',done[index]);button.querySelector('.section-done').textContent=done[index]?'✓':'';});
    $$('[data-finish-check]').forEach(item=>{const complete=checks[item.dataset.finishCheck]===true;item.classList.toggle('is-complete',complete);item.querySelector('span').textContent=complete?'Done':'To do';});
    $('.save-status').textContent=workStatus(r,workStorage);$('#action-count').textContent=r.events.length+' actions';
  }
  function logEvent(event){r.events.push({time:new Date().toISOString(),kind:event.kind,message:event.message.slice(0,600)});r.events=retainExperimentEvents(s,r.events);$('#bench-log').innerHTML=eventList(r,s);}
  function action(id,value){
    const result=s.track==='hardware'?applyHardwareAction(s.id,r.state,id):applyWorkspaceAction(s.id,r.state,id,value);
    r.state=result.state;
    const inspectOnly=id==='enable-assembly'||id.startsWith('inspect-')||(s.track==='hardware'&&id.startsWith('view-'));
    if(!inspectOnly){r.verified=false;r.closed=false;$('#verify-result').textContent='';$('#experiment-result').textContent=language.setupChanged;}
    logEvent(result);save();
    if(id!=='inspect-command')renderBench();
    $('#action-feedback').textContent=result.message;$('#action-feedback').dataset.kind=result.kind;refreshStatus();document.dispatchEvent?.(new CustomEvent('cole:lab-state-change',{detail:{id:s.id,changed:!inspectOnly}}));
    return result;
  }
  function ask(question,reply){
    requester.cancel();
    $('#question-response').textContent=reply.answer;
    $('#reply-source').textContent=reply.kind==='casual'?'Fast character · extra chat, not a case clue':reply.accepted?'Case reply · compare it with your evidence':'';
    let pair=null;
    if(reply.accepted){pair={question:question.trim(),answer:reply.answer,source:reply.kind==='casual'?'Fast character · extra chat':'Case reply'};chatPairs.push(pair);if(chatPairs.length>8)chatPairs.shift();renderChat();}
    requester.enrich(question,reply,answer=>{if(!pair)return;pair.answer=answer;pair.source='AI extra reply · not case evidence';$('#question-response').textContent=answer;$('#reply-source').textContent='AI extra reply · check it before trusting it; not a case clue';renderChat();});
    const suggestions=$('#question-suggestions');
    suggestions.replaceChildren();
    const prompts=Array.isArray(reply.suggestions)?[...new Set(reply.suggestions.filter(value=>typeof value==='string'&&value.trim()&&value.length<=240).map(value=>value.trim()))].slice(0,3):[];
    suggestions.hidden=prompts.length===0;
    if(prompts.length){
      const help=document.createElement('p');help.className='panel-help';help.textContent=language.followUpPrompt;suggestions.appendChild(help);
      for(const prompt of prompts){
        const button=document.createElement('button');button.type='button';button.className='question-button interview-followup';button.textContent=prompt;
        button.addEventListener('click',()=>{ask(prompt,answerQuestion(s,prompt,r.state,readQuestionEvents(r.events)));$('#student-question').focus({preventScroll:true});});
        suggestions.appendChild(button);
      }
    }
    const event=questionEvent(question,reply);
    if(event){logEvent(event);r.closed=false;save();refreshStatus();}
  }
  // Mount the workbench once without repairing the ticket or awarding progress.
  // It remains paused while either of the other pages is open.
  renderBench();if(s.track==='hardware'&&!r.state.assemblyEnabled)action('enable-assembly');
  jumpToSection(route?.section??(labView?.id===s.id?labView.section:1),false,false,false);
  $('#question-form').addEventListener('submit',event=>{
    event.preventDefault();
    const input=$('#student-question'),question=input.value;
    const reply=answerQuestion(s,question,r.state,readQuestionEvents(r.events));
    ask(question,reply);input.value='';input.focus({preventScroll:true});
  });
  $$('[data-question]').forEach(button=>button.addEventListener('click',()=>{const i=Number(button.dataset.question);if(!r.questions.includes(i))r.questions.push(i);button.setAttribute('aria-pressed','true');button.querySelector('span').textContent='Read';ask(s.questions[i].label,answerQuestion(s,s.questions[i].label,r.state,readQuestionEvents(r.events)));}));
  $$('[data-clue]').forEach(button=>button.addEventListener('click',()=>{const clue=s.clues.find(c=>c.id===button.dataset.clue);if(clue.requiresFact&&!inquiryProgress(s,r.events).found.includes(clue.requiresFact)){$('#evidence-detail').textContent=s.intake.missing;$('#student-question').focus();return;}if(!r.evidence.includes(clue.id))r.evidence.push(clue.id);button.classList.add('logged');button.setAttribute('aria-pressed','true');button.querySelector('span').textContent='Added';$('#evidence-detail').textContent=clue.text;$('#evidence-list').innerHTML=evidenceList(s,r);$('#clue-count').textContent=r.evidence.length+' clues';save();refreshStatus();}));
  ['plan','notes','reflection'].forEach(field=>$('#'+field).addEventListener('input',event=>{r[field]=event.target.value;r.closed=false;if(field==='plan'){$('#experiment-hypothesis').textContent=r.plan||language.hypothesisEmpty;$('#experiment-result').textContent=language.hypothesisChanged;}save();refreshStatus();}));
  function runHypothesisTest(prediction=r.plan){
    if(typeof prediction!=='string'||prediction.trim().length<12){jumpToSection(1,true);const drawer=$('#plan').closest?.('details');if(drawer)drawer.open=true;$('#plan').focus();showNotice(language.hypothesisRequired);return false;}
    if(s.track!=='hardware')action('run-check',s.track==='coding'?{code:$('#coding-editor').value}:undefined);
    const result=s.track==='hardware'?verifyHardware(s.id,r.state):verifyWorkspace(s.id,r.state);
    r.verified=result.ok;r.closed=false;
    const observed=(result.ok?language.verifiedStatus:language.taskNotReady)+' '+result.message;
    logEvent({kind:result.ok?'success':'warning',message:'Hypothesis test — '+prediction.trim().slice(0,140)+' / Observed: '+observed});
    $('#experiment-result').textContent=observed+' '+language.testResultPrompt;
    $('#verify-result').textContent=(result.ok?'✓ ':'Try again: ')+result.message;
    save();refreshStatus();return true;
  }
  $('#run-hypothesis-test').addEventListener('click',()=>runHypothesisTest());
  $('#verify-task').addEventListener('click',()=>{const result=currentTaskResult();r.verified=result.ok;r.closed=r.closed&&result.ok;logEvent({message:'Verification: '+result.message,kind:result.ok?'success':'warning'});$('#verify-result').textContent=(result.ok?'✓ ':'Try again: ')+result.message;save();refreshStatus();});
  $('#close-ticket').addEventListener('click',()=>{
    const check=currentTaskResult();
    if(!check.ok){r.verified=false;r.closed=false;save();refreshStatus();$('#verify-result').textContent=language.taskNotReady+' '+check.message;return;}
    const inquiry=inquiryProgress(s,r.events);
    if(!inquiry.complete){jumpToSection(1,true);$('#student-question').focus();showNotice(inquiry.message);return;}
    if(r.evidence.length<2||r.plan.trim().length<12){jumpToSection(1,true);for(const field of ['#evidence-detail','#plan']){const drawer=$(field).closest?.('details');if(drawer)drawer.open=true;}showNotice(language.cluesPlanRequired);$('#plan').focus({preventScroll:true});$('#plan').scrollIntoView({block:'nearest',behavior:'instant'});return;}
    if(r.notes.trim().length<15||r.reflection.trim().length<15){$('#verify-result').textContent=language.writingRequired;$('#notes').focus();return;}
    r.verified=true;r.closed=true;save();refreshStatus();showNotice(language.completionLead);openReport(s,r);
  });
  $('#reading-toggle').addEventListener('click',event=>{const on=shell.classList.toggle('larger-reading');event.target.setAttribute('aria-pressed',String(on));});
  tabs.forEach((button,index)=>{
    button.addEventListener('click',()=>jumpToSection(button.dataset.labSection,true,true));
    button.addEventListener('keydown',event=>{
      const target={ArrowLeft:(index+2)%3,ArrowRight:(index+1)%3,Home:0,End:2}[event.key];
      if(target===undefined)return;
      event.preventDefault();jumpToSection(target+1,true,true);
    });
  });
  $$('[data-jump-section]').forEach(button=>button.addEventListener('click',()=>jumpToSection(button.dataset.jumpSection,true)));
  $('#saving-options').addEventListener('click',()=>{const options=$('#work-privacy details');options.open=true;options.querySelector('summary').focus({preventScroll:true});options.scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});});
  $('#report-button').addEventListener('click',()=>openReport(s,r));$('#finish-report').addEventListener('click',()=>openReport(s,r));
  $('#reset-ticket').addEventListener('click',()=>{$('#reset-confirm').hidden=false;});$('#cancel-reset').addEventListener('click',()=>{$('#reset-confirm').hidden=true;});
  $('#confirm-reset').addEventListener('click',()=>{delete store.labs[s.id];labView={id:s.id,section:1};history.replaceState(null,'',labPageHash(s.id,1,{mode:currentMode(),sequence:context.sequence}));save();renderRoute(false);});
  $('#dialog-close').addEventListener('click',()=>$('#lab-dialog').close());refreshStatus();
  classroomConnection=classroomSharingPaused?null:attachClassroomLab({scenarioId:s.id,record:r,storageKey,onRestore:work=>{store.labs[s.id]=normalizeLabRecord(s,work);save();renderRoute(false);}});
  return {runHypothesisTest,currentTaskResult,syncRoute,dispose(){requester.dispose();chatPairs.length=0;}};
}

function hardwareCableSummary(h){return [
  ['AC power',h.acConnected],['HDMI PC end',h.pcVideoConnected!==false],['HDMI monitor end',h.signalConnected],
  ['ATX 24-pin',h.atxConnected],['CPU 8-pin',h.cpuPowerConnected],['GPU power',h.gpuPowerConnected],
  ['SATA data',h.sataDataConnected],['SATA power',h.sataPowerConnected],['Front panel',h.frontPanelConnected],
  ...(h.assemblyEnabled?[['CPU fan',h.assembly.cpuFanConnected]]:[])
].map(([label,connected])=>label+': '+(connected?'connected':'disconnected')).join('\n')+'\nPC video output: '+h.videoPort+'\nMonitor source: '+h.monitorInput;}
function reportText(s,r){return `COLE LEARNING LABS — INVESTIGATION REPORT\n${s.id} · ${s.title}\nGrades ${s.grade} · ${tracks[s.track].name}\nStatus: ${r.closed?'DELIVERED':r.verified?'TECHNICALLY VERIFIED — TICKET OPEN':'IN PROGRESS'}\n\nORIGINAL TASK\n${s.goal}\n\nEVIDENCE\n${r.evidence.map(id=>'- '+(s.clues.find(c=>c.id===id)?.text||id)).join('\n')||'No evidence recorded.'}\n\nQUESTIONS I ASKED\n${readQuestionEvents(r.events).map(pair=>'Q: '+pair.question+'\nRequester: '+pair.answer).join('\n\n')||'No interview questions recorded.'}\n\nWORKING HYPOTHESIS\n${r.plan||'Not recorded.'}\n\nTEST NOTES\n${r.notes||'Not recorded.'}${s.track==='coding'?'\n\nSAVED PRACTICE CODE\n'+(r.state.code||'Not recorded.')+'\n\nPRACTICE OUTPUT\n'+(Array.isArray(r.state.output)?r.state.output.join('\n'):r.state.output||'No output recorded.'):''}\n\nEXPERIMENT RECORD\n${experimentReport(r)}${s.track==='hardware'?'\n\nCABLE CONNECTIONS\n'+hardwareCableSummary(r.state):''}${s.track==='hardware'&&r.state.assemblyEnabled?'\n\nDETAILED ASSEMBLY STATUS\n'+['panel','psu','board','cooler','gpu','ssd'].map(group=>{const values=r.state.assembly[group+'Screws'];return group+': '+values.filter(Boolean).length+'/'+values.length+' screws secured';}).join('\n')+'\nThermal interface: '+r.state.assembly.paste+'\nCPU fan lead: '+(r.state.assembly.cpuFanConnected?'connected':'disconnected')+'\nCPU retention: '+(r.state.assembly.retentionOpen?'open':'closed')+'\nMemory clips: '+(r.state.assembly.ramClipsOpen?'open':'closed')+'\nPCIe latch: '+(r.state.assembly.pcieLatchOpen?'open':'closed'):''}\n\nACTION LOG\n${r.events.filter(e=>!readQuestionEvents([e]).length).map(e=>'- '+eventMessage(e)).join('\n')||'No actions recorded.'}\n\nREFLECTION\n${r.reflection||'Not recorded.'}\n\nThis is a simulated learning activity. Private-session work stays on this page unless exported or explicitly saved on this device. If you explicitly join an enabled classroom, assigned lab drafts and submitted snapshots may be shared with that teacher. Technical progress is student-reported; teachers review and grade submissions.\n`;}
function openReport(s,r,customContent){
  cancelHardwareInteraction($('#workspace'));
  reportCleanup?.();
  const content=typeof customContent==='string'?customContent:reportText(s,r),panel=$('#dialog-content'),dialog=$('#lab-dialog');
  panel.innerHTML=[
    '<p class="eyebrow">STUDENT REPORT</p><h2>'+esc(s.id)+' · '+esc(s.title)+'</h2>',
    '<p>Review your notes for names, emails, student IDs, passwords, and private school details. Close this report and edit your lab notes to remove them before exporting. This tool does not automatically detect personal information.</p>',
    '<label class="lab-field">Review your report<textarea id="report-text" rows="10" readonly>'+esc(content)+'</textarea></label>',
    '<section class="report-plain" aria-labelledby="report-save-heading"><h3 id="report-save-heading">Download or save your work</h3><p>A plain-text copy can be read by anyone who can access it. Use only your teacher’s approved submission process. Saving this file does not submit it to your teacher. A save or share destination you choose, including a cloud folder, can receive the report.</p>',
    '<label class="privacy-checkbox"><input id="plain-report-confirm" type="checkbox"><span>I reviewed the report for private information and have approval to export an unencrypted copy.</span></label>',
    '<div class="button-row"><a class="button button-outline" id="download-report" download="'+esc(reportFilename(s.id))+'" aria-describedby="report-save-help" aria-disabled="true">Download .txt report</a><button class="button button-outline" id="share-report" disabled hidden>Save or share .txt</button><button class="button button-outline" id="copy-report" disabled>Copy report</button><button class="button button-outline" id="select-report" disabled>Select report text</button></div>',
    '<p id="report-save-help">On a Chromebook or Microsoft Edge, choose Download .txt, then check the browser’s Downloads list. On a tablet, choose Download .txt or, when offered, Save or share .txt and select your school-approved Files location. Your device or school may restrict these options. Keep this page open until you have checked the saved file.</p>',
    '<p id="report-plain-status" role="status" aria-live="polite"></p><p id="report-manual-help" hidden>Use Ctrl+C to copy the selected report on a keyboard. On a tablet, touch and hold the report, choose Select all, then Copy. Paste into your school-approved document app and save there. If copying is restricted, ask your teacher for the approved way to keep your work. Clear the clipboard before sharing this device.</p></section>',
    '<section class="report-encryption"><h3>Encrypt for your teacher</h3><p>Use a public key supplied through your teacher’s trusted school channel. Anyone with its matching private key and passphrase can decrypt this report. Encryption does not verify who wrote it.</p>',
    '<label class="lab-field">Teacher public key (.cllpub)<input id="report-public-key" type="file" accept=".cllpub"></label>',
    '<p class="report-fingerprint" id="report-fingerprint">No public key selected.</p>',
    '<label class="privacy-checkbox"><input id="report-key-confirm" type="checkbox" disabled><span>I compared this fingerprint with the one supplied by my teacher through a trusted school channel.</span></label>',
    '<div class="button-row"><button class="button" id="encrypt-report" disabled>Encrypt this report</button><a class="button button-outline" id="encrypted-report-download" download="cole-lab-report.cllreport" hidden>Download encrypted report</a></div>',
    '<p role="status" id="report-encryption-status"></p><p><a href="secure-reports.html" target="_blank" rel="noopener noreferrer">Teacher key setup and report reader ↗</a>. Submit the downloaded file through your school’s approved process. This does not connect to Google Classroom. Your school’s submission system can still show your account identity and attachment metadata to authorized people.</p></section>'
  ].join('');
  let active=true,selection=0,publicFile='',plainArtifact=null,sharePending=false;
  const urls=createReportURLs(),keyInput=$('#report-public-key'),confirm=$('#report-key-confirm'),encrypt=$('#encrypt-report'),encrypted=$('#encrypted-report-download'),status=$('#report-encryption-status'),fingerprint=$('#report-fingerprint'),plain=$('#plain-report-confirm'),plainLink=$('#download-report'),copy=$('#copy-report'),share=$('#share-report'),select=$('#select-report'),plainStatus=$('#report-plain-status'),manualHelp=$('#report-manual-help');
  const current=token=>active&&dialog.open&&panel.isConnected&&selection===token;
  const plainAllowed=()=>active&&dialog.open&&panel.isConnected&&plain.checked;
  function clearPlain(){const url=plainLink.getAttribute('href');if(url)urls.release(url);plainArtifact=null;plainLink.removeAttribute('href');plainLink.setAttribute('aria-disabled','true');copy.disabled=true;select.disabled=true;share.disabled=true;share.hidden=true;plainStatus.textContent='';manualHelp.hidden=true;}
  function revokeLinks(){urls.clear();encrypted.hidden=true;encrypted.removeAttribute('href');plain.checked=false;clearPlain();}
  function cleanup(){if(!active)return;active=false;selection++;publicFile='';revokeLinks();panel.replaceChildren();dialog.removeEventListener('close',cleanup);if(reportCleanup===cleanup)reportCleanup=null;}
  reportCleanup=cleanup;dialog.addEventListener('close',cleanup);
  keyInput.addEventListener('change',async()=>{
    const token=++selection;publicFile='';confirm.checked=false;confirm.disabled=true;encrypt.disabled=true;fingerprint.textContent='Checking public key…';status.textContent='';revokeLinks();
    try{
      const file=keyInput.files?.[0];
      if(!file||!file.name.toLowerCase().endsWith('.cllpub')||file.size<1||file.size>16000)throw new Error('Invalid file.');
      const text=await file.text(),cryptoModule=await import('./report-crypto.js?release=20261020-chromebook25');
      const result=await cryptoModule.inspectPublicKey(text);
      if(!current(token))return;
      publicFile=text;fingerprint.textContent=result.fingerprint;confirm.disabled=false;
    }catch{if(current(token)){fingerprint.textContent='Public key could not be read. Use the .cllpub file supplied by your teacher.';}}
  });
  confirm.addEventListener('change',()=>{encrypt.disabled=!confirm.checked||!publicFile;});
  encrypt.addEventListener('click',async()=>{
    if(!confirm.checked||!publicFile)return;
    const token=selection,key=publicFile;
    encrypt.disabled=true;keyInput.disabled=true;confirm.disabled=true;encrypted.hidden=true;status.textContent='Encrypting on this device…';
    try{
      const cryptoModule=await import('./report-crypto.js?release=20261020-chromebook25');
      const protectedReport=await cryptoModule.encryptReport(key,{report:content,alias:cryptoModule.generateAlias()});
      if(!current(token))return;
      const url=urls.create(new Blob([protectedReport],{type:'application/octet-stream'}));encrypted.href=url;encrypted.hidden=false;
      status.textContent='Encrypted report ready. Only holders of the matching private key and passphrase can open its contents. Upload through your school’s approved process.';
    }catch{if(current(token))status.textContent='The report could not be encrypted. Check the teacher key and use a current browser over HTTPS.';}
    finally{if(current(token)){keyInput.disabled=false;confirm.disabled=false;encrypt.disabled=!confirm.checked;}}
  });
  encrypted.addEventListener('click',()=>{const url=encrypted.getAttribute('href');if(url)urls.requested(url);});
  plain.addEventListener('change',()=>{
    clearPlain();
    if(!plainAllowed())return;
    copy.disabled=false;select.disabled=false;
    try{
      plainArtifact=createTextReport(content,s.id);
      share.hidden=!canShareTextReport(plainArtifact);share.disabled=sharePending;
      try{plainLink.href=urls.create(plainArtifact.blob);plainLink.removeAttribute('aria-disabled');plainStatus.textContent='Ready: '+plainArtifact.filename+'. Choose a save option above.';}
      catch{plainStatus.textContent='This browser could not prepare a download. Use Copy report, Select report text, or the available device save option.';}
    }catch{plainStatus.textContent='This browser could not prepare a file. Use Copy report or Select report text.';}
  });
  plainLink.addEventListener('click',event=>{const url=plainLink.getAttribute('href');if(!plainAllowed()||!plainArtifact||!url){event.preventDefault();return;}urls.requested(url);plainStatus.textContent='Download requested: '+plainArtifact.filename+'. Check Downloads or Files and open the file to confirm your work was saved. This page cannot confirm that the browser saved it.';});
  function selectText(){if(!plainAllowed())return;const text=$('#report-text');try{text.focus?.();text.select();}catch{/* Device text controls remain available when programmatic selection is restricted. */}manualHelp.hidden=false;plainStatus.textContent='Select and copy the report text above, then paste and save in your school-approved document app.';}
  select.addEventListener('click',selectText);
  copy.addEventListener('click',async()=>{if(!plainAllowed())return;try{await navigator.clipboard.writeText(content);if(plainAllowed())plainStatus.textContent='Report copied. Paste and save in your school-approved document app. Clear the clipboard before sharing this device.';}catch{if(plainAllowed())selectText();}});
  share.addEventListener('click',async()=>{
    if(!plainAllowed()||!plainArtifact||sharePending)return;
    const artifact=plainArtifact;sharePending=true;share.disabled=true;plainStatus.textContent='Choose a school-approved destination in your device’s save or share menu.';
    const result=await shareTextReport(artifact);
    sharePending=false;
    if(!plainAllowed())return;
    share.disabled=false;
    if(plainArtifact!==artifact)return;
    plainStatus.textContent=result==='opened'?'The device save or share menu was opened. Check the chosen destination and open the file to confirm it was saved. This page cannot confirm saving or submission.':result==='cancelled'?'The save or share menu was cancelled or had no destination. Nothing is confirmed saved. Try Download .txt or Copy report.':'Device saving or sharing is unavailable or blocked. Try Download .txt, Copy report, or Select report text.';
  });
  dialog.showModal();
}

function curriculumDownloads(){return `<section class="wrap section curriculum-downloads" aria-labelledby="curriculum-title"><p class="eyebrow">PRINTABLE COMPANIONS</p><h2 id="curriculum-title">A place to record your thinking.</h2><p>Use the on-screen labs for the interactive, accessible workflow. These optional PDFs support printing and offline notes; the workbook is selectable text but is not a tagged PDF.</p><div class="curriculum-grid"><article><h3>Student investigation workbook</h3><p>Blank prompts for the three lab sections, questions, hypothesis tests, experiments, and reflection. Record your own evidence from the current lab.</p><a class="button button-outline" href="assets/cole-learning-labs-student-workbook.pdf" download>Download workbook <span class="curriculum-file">PDF · 6 pages · 12 KB</span></a></article><article><h3>Practice quizzes</h3><p>Unmarked questions for a quick check or class discussion. These are public practice materials. Use a class alias or leave the name line blank.</p><a class="button button-outline" href="assets/cole-learning-labs-pop-quizzes.pdf" download>Download practice quizzes <span class="curriculum-file">PDF · 8 pages · 120 KB</span></a></article></div><p class="curriculum-note">Keep names, emails, student IDs, and private school details out of your notes. Submit work only through your teacher’s school-approved process. Downloading these files does not upload lab work.</p></section>`;}
function educators(){return renderTeachingPage(SCENARIOS)+curriculumDownloads()+'<section class="wrap section prose"><h2>Classroom preparation</h2><p>Complete the selected lab on your actual school device and network before the lesson. Check touch, keyboard navigation, zoom, downloads and your approved submission route. Support levels are teaching choices; students can keep safety and accessibility help available.</p><p>Independent work stays in this page’s memory by default. Device saving is optional and unencrypted. Use the <a href="secure-reports.html">teacher encryption-key setup and local report reader</a> when approved by your school. Keep private answer keys and grading materials in your school’s authenticated teacher resources.</p><p><a href="#capstone">Classroom opening day capstone</a> connects all five pathways. <a href="classroom.html">Classroom options</a> includes a fictional teacher demo; real enrollment and live AI remain locked pending the required privacy and school review. The launcher and preparation prompts contain public fictional lesson content.</p><p>Share the <a href="school-it.html">School IT review</a> for browser requirements and district filtering review. These resources are created by Mx. Cole toward a future goal of teaching Computer Technology through CTE.</p></section>';}
function guide(){return "<section class=\"wrap page-intro\"><p class=\"eyebrow\">STUDENT GUIDE</p><h1>One investigation.<br><em>Three clear steps.</em></h1><p>You do not need to know the answer before you begin. Your request, tools, and explanation each have their own page. Follow the numbered pages, then go back whenever you need to review a clue or test another idea.</p></section><section class=\"wrap section guide-layout\"><aside><h2>Ready to begin?</h2><p>Choose a lab, read the goal, and follow the numbered pages.</p>"+routeLink('labs','Choose a lab ↗')+'</aside>'+"<div class=\"prose\"><h2>New to a topic?</h2><p>Choose a beginner lab from All virtual labs. Explore the parts or concepts, try a guided job, and check what you learned. Beginner work stays in this page’s memory; open My report to keep a copy before leaving.</p><h2>1. Request &amp; clues</h2><p>Read the request and look for what is missing. Detailed requests include useful context; incomplete requests need a follow-up about the missing detail shown on screen. Write your own question for the virtual requester or choose a starter question. Replies use built-in fictional case facts on this device; this is a scripted simulation and may ask you to rephrase. Collect at least two clues, then write a hypothesis: what might be happening, and why?</p><h2>2. Workbench &amp; test</h2><p>Read the workbench’s short ticket instruction. Use Back: Request & clues or the first numbered button to review the request and clues. Your workbench stays as you left it when you return. Hardware labs show the relevant tools, components and connection choices. Choose Move parts or Connect cables to drag a part or plug to its matching labeled target. Part controls and the selected tool’s controls offer the same actions with keyboard or touch. Power off and unplug before internal work. For a different repair, open All workbench tools (optional) and choose Show complete controls. Fans and indicators follow the virtual power and connections; read the startup result and monitor as well. Use Test PC and Open lesson to check the original task. Software labs include local inspection tools with suggested commands; no real commands or network tests run.</p><p>Make one change at a time. Save edited workspace settings before testing. Choose Run hypothesis test, read the observed result, and decide whether it supports your idea. A successful task test does not judge your written explanation.</p><h2>3. Check &amp; explain</h2><p>Check the original task. Describe your changes, test results, and whether the evidence supports your hypothesis. Choose Finish investigation &amp; open report. Review the report, including your questions and replies. In Download or save your work, confirm that you reviewed it, then choose Download .txt report. Check Downloads on a Chromebook or Microsoft Edge. Tablets can also offer Save or share .txt; choose your school-approved Files location. Open the saved file before leaving. Saving is separate from submitting through your teacher’s approved process.</p><h2>Need to go back?</h2><p>Use Back, Next, or a numbered button to open Request & clues, Workbench & test, or Check & Explain. You can also use your browser’s Back and Forward buttons between pages of the same lab. Your unfinished questions, edited settings, code drafts, notes, and equipment stay in place while you move through this lab. Device saving remains optional. The numbered buttons also support Left/Right Arrow, Home, and End. The larger-text button can make instructions easier to read.</p><h2>Before leaving</h2><p>Private sessions do not automatically save your work. Open My report to export it, or use Saving &amp; privacy to choose device saving on an approved personal browser profile. Device-saved work is not encrypted; clear it before sharing the profile. Do not enter names, emails, student IDs, passwords, or private school details. The question filter catches some obvious private details, but cannot detect everything.</p><h2>Keep it virtual</h2><p>Use only the simulated equipment and fictional information in the lab. Ethical cybersecurity activities require the on-screen scope agreement. Never test a real person’s account, device, network, or website without authorization.</p></div></section>"+curriculumDownloads();}
function connect(){return `<section class="wrap page-intro"><p class="eyebrow">LET’S CONNECT</p><h1>Good technology<br><em>starts with people.</em></h1><p>For professional opportunities, project conversations, or ideas for technology education, connect with me on LinkedIn.</p>${routeLink('about','About my background →','text-link')}</section><section class="wrap connect-grid section">${[{name:'LinkedIn',type:'PROFESSIONAL CONNECTIONS',copy:'Connect with Alan “Al” Cole.',url:'https://www.linkedin.com/in/alan91cole'},{name:'GitHub',type:'SOURCE & PROJECTS',copy:'Explore code, documentation, and research.',url:'https://github.com/AL91Cole'},{name:'Credly',type:'CREDENTIALS',copy:'View my public credentials and achievements.',url:'https://www.credly.com/users/alan91cole'},{name:'TryHackMe',type:'CONTINUING LEARNING',copy:'Visit my cybersecurity learning profile.',url:'https://tryhackme.com/p/Alan91Cole'}].map(p=>`<a href="${p.url}" target="_blank" rel="noopener noreferrer"><p class="eyebrow">${p.type}</p><h2>${p.name} ↗</h2><p>${p.copy}</p></a>`).join('')}</section>`;}
function privacy(){return privacyPage();}

function checkCapstoneState(id,state){const s=SCENARIOS.find(item=>item.id===id);return s?.track==='hardware'?verifyHardware(id,state):verifyWorkspace(id,state);}
function renderRoute(preserveDraft=true){const route=learningRoute(location.hash);if(preserveDraft!==false&&labNavigation?.syncRoute(route))return false;labNavigation=null;disposeHardware($('#workspace'));if(preserveDraft!==false)preserveCodeDraft();reportCleanup?.();reportCleanup=null;classroomConnection?.dispose();classroomConnection=null;routeCleanup?.();routeCleanup=null;currentLab=null;document.body.classList.remove('lab-view');let {page,id}=route;let html,title;if(page==='learn'){const foundation=getFoundation(id);if(foundation){id=foundation.id;document.body.classList.add('lab-view');html=renderFoundationLab(foundation,foundationRecordFor(id));title=`${foundation.code} · ${foundation.title}`;}else{html=`<section class="wrap page-intro"><h1>Choose a beginner lab.</h1><p>Pick one of the five topics to start learning.</p>${routeLink('labs','All virtual labs →')}</section>`;title='Beginner lab not found';}}else if(page==='lab'){const s=SCENARIOS.find(x=>x.id===id);if(s){document.body.classList.add('lab-view');html=(route.sequence?'<div class="capstone-return"><strong>Classroom opening day</strong><a href="#capstone">← Return to your five work orders</a></div>':'')+labPage(s);title=`${s.id} · ${s.title}`;}else{html=`<section class="wrap page-intro"><h1>That ticket is not on this bench.</h1><p>Choose one of the available investigations.</p>${routeLink('labs','All virtual labs →')}</section>`;title='Lab not found';}}else if(page==='capstone'){html=renderCapstone(store.labs,checkCapstoneState);title='Classroom opening day';}else{const pages={home:[home,'Alan Cole'],projects:[projectPage,'Projects'],about:[about,'About Alan Cole'],labs:[library,'Virtual labs'],educators:[educators,'For educators'],guide:[guide,'Student guide'],connect:[connect,'Connect'],privacy:[privacy,'Privacy & accessibility']};if(!Object.hasOwn(pages,page))page='home';if(page==='labs'&&Object.hasOwn(tracks,id))libraryTrack=id;[html,title]=[pages[page][0](),pages[page][1]];}
$('#main').innerHTML=html;document.title=`${title} · Cole Learning Labs`;$$('#site-nav a').forEach(a=>{const active=a.hash===`#${['lab','learn'].includes(page)?'labs':page}`;if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#site-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');
if(page==='labs'){labCards();$$('.track-filters [data-track]').forEach(b=>b.addEventListener('click',()=>{libraryTrack=b.dataset.track;history.replaceState(null,'','#labs');renderRoute();}));$('#grade-filter').addEventListener('change',e=>{libraryGrade=e.target.value;labCards();});$('#lab-search').addEventListener('input',e=>{libraryQuery=e.target.value;labCards();});}if(currentLab){const labController=bindLab(currentLab,route,{onModeChange:mode=>cleanupLearning.setMode?.(mode)}),s=currentLab,r=store.labs[s.id];labNavigation=labController;const cleanupLearning=mountLabLearning($('#main'),{scenario:s,record:r,mode:route.mode,sequence:route.sequence,onSave:()=>{save();$('#bench-log').innerHTML=eventList(r);$('#action-count').textContent=r.events.length+' actions';},onTest:prediction=>labController.runHypothesisTest(prediction),getResult:()=>labController.currentTaskResult()});routeCleanup=()=>{labController.dispose();cleanupLearning?.();};}
if(page==='learn'&&getFoundation(id)){const foundation=getFoundation(id),controller=mountFoundationLab($('#main'),{lab:foundation,record:foundationRecordFor(id),onChange:record=>{foundationRecords[id]=record;},onReport:()=>openReport({id:foundation.code,title:foundation.title,grade:foundation.grade||'7–12'}, {},foundationReport(id,foundationRecords[id]))});routeCleanup=()=>controller.dispose();$('#dialog-close').addEventListener('click',()=>$('#lab-dialog').close());}
if(page==='educators')routeCleanup=mountTeachingPage($('#main'),SCENARIOS,{notify:showNotice});
if(page==='capstone'){const s=SCENARIOS.find(item=>item.id==='CODE-503'),r=recordFor(s);bindWorkPrivacy(s);routeCleanup=mountCapstone($('#main'),{record:r,onSave:save,onReport:()=>openReport({id:'CAP-601',title:'Classroom opening day',grade:'7–12'},r,capstoneReport(store.labs,checkCapstoneState))});$('#dialog-close').addEventListener('click',()=>$('#lab-dialog').close());}
window.scrollTo(0,0);}
$('#menu-toggle').addEventListener('click',()=>{const on=$('#site-nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(on));});
$('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({block:'start'});});
window.addEventListener('hashchange',()=>{if(renderRoute()!==false)$('#main').focus({preventScroll:true});});
renderRoute();
